function localizeHtml (html, lang) {
    if (lang !== 'zh' || !html) return html;
    var D = I18N_DICT;
    var out = html;
    // Remove the old in-iframe runtime i18n observer. It probes language from
    // inside the isolated iframe (where the host Scratch locale is invisible)
    // and its reverse dictionary can flip our static Chinese back to English.
    out = out.replace(/<script data-rw-i18n="1">[\s\S]*?<\/script>/g, '');
    // HTML text nodes:  >English<
    out = out.replace(/>\s*([^<>]{1,60}?)\s*</g, function (m, en) {
        return D[en] ? m.split(en).join(D[en]) : m;
    });
    // Double-quoted strings (HTML attributes + JS strings):  "English"
    out = out.replace(/"([^"\\\n]{1,80})"/g, function (m, en) {
        return D[en] ? m.split(en).join(D[en]) : m;
    });
    // Single-quoted JS strings:  'English'
    out = out.replace(/'([^'\\\n]{1,80})'/g, function (m, en) {
        return D[en] ? m.split(en).join(D[en]) : m;
    });
    // Template literals:  `English`
    out = out.replace(/`([^`]{1,80})`/g, function (m, en) {
        return D[en] ? m.split(en).join(D[en]) : m;
    });
    return out;
}

export default localizeHtml;
